function ScrollToTop() {
    try {
        const [isVisible, setIsVisible] = React.useState(false);

        React.useEffect(() => {
            const toggleVisibility = () => {
                if (window.pageYOffset > 200) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                }
            };

            window.addEventListener('scroll', toggleVisibility);
            return () => window.removeEventListener('scroll', toggleVisibility);
        }, []);

        const scrollToTop = () => {
            window.scrollTo({
                top: 0,
                behavior: 'smooth'
            });
        };

        return (
            <button
                class="scroll-to-top"
                data-name="scroll-to-top" 
                data-file="lib/components/ScrollToTop.min.js"
                onClick={scrollToTop}
                className={`fixed bottom-6 right-6 w-12 h-12 bg-black text-white rounded-full shadow-lg hover:bg-gray-800 transition-all duration-300 z-40 flex items-center justify-center cursor-pointer ${
                    isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'
                }`}
                style={{
                    boxShadow: '0 0 20px rgba(0, 0, 0, 0.5), 0 0 40px rgba(255, 255, 255, 0.5), 0 4px 15px rgba(0, 0, 0, 0.5)'
                }}
                aria-label="Scroll to top"
            >
                <i className="fas fa-chevron-up text-lg"></i>
            </button>
        );
    } catch (error) {
        console.error('ScrollToTop component error:', error);
        return null;
    }
}